def dijkstra(sources):
    dist = [1e18] * len(S)
    pq = []
    for v in sources:
        if v in Sidx:
            dist[Sidx[v]] = 0.0
            heapq.heappush(pq, (0.0, Sidx[v]))
    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u] + 1e-15:
            continue
        for w, el in ADJ.get(u, ()):
            nd = d + el
            if nd < dist[w] - 1e-15:
                dist[w] = nd
                heapq.heappush(pq, (nd, w))
    return dist


